original_card.content:
{% if states('sensor.siemens_016050395510002818_bsh_common_status_operationstate') in ['unknown', 'unavailable'] %}
<ha-icon icon="mdi:dishwasher-alert"></ha-icon> **Diskmaskin · Kontakt saknas**

Programstatus och återstående tid kan inte hämtas.
{% else %}
{% set operation = states('sensor.siemens_016050395510002818_bsh_common_status_operationstate').split('.')[-1] %}
{% set progress = states('sensor.siemens_016050395510002818_bsh_common_option_programprogress') %}
{% set finish = as_timestamp(states('sensor.siemens_016050395510002818_bsh_common_option_remainingprogramtime'), none) %}
<ha-icon icon="mdi:dishwasher"></ha-icon> **Diskmaskin · {{ {'Run': 'Kör program', 'Pause': 'Pausad', 'ActionRequired': 'Åtgärd krävs'}.get(operation, 'Inväntar status') }}**

{% if is_number(progress) %}**{{ progress | float | round(0) | int }} %** klart{% else %}Förlopp saknas{% endif %} · {% if operation == 'Pause' %}Tid uppdateras när programmet fortsätter{% elif operation == 'ActionRequired' %}Kontrollera maskinen{% elif finish is not none and finish > as_timestamp(now()) %}{% set minutes = ((finish - as_timestamp(now())) / 60) | round(0, 'ceil') | int %}Cirka {% if minutes >= 60 %}{{ minutes // 60 }} h {% endif %}{{ minutes % 60 }} min kvar{% else %}Inväntar tidsprognos{% endif %}

{% endif %}

style.ha-markdown$:
{% set indicator_state = states('sensor.siemens_016050395510002818_bsh_common_status_operationstate') %}
ha-icon {
  color: {{ '#FFC107' if indicator_state == 'BSH.Common.EnumType.OperationState.Pause' else '#FF9800' if indicator_state in ['BSH.Common.EnumType.OperationState.ActionRequired', 'unknown', 'unavailable'] else '#64b5c6' }};
  --mdc-icon-size: 24px;
  display: inline-block;
  margin-right: 6px;
  vertical-align: middle;
  animation: {{ 'appliance-motion 1.6s ease-in-out infinite' if indicator_state == 'BSH.Common.EnumType.OperationState.Run' else 'none' }};
}
@keyframes appliance-motion { 0%,100% { transform:rotate(-12deg); } 50% { transform:rotate(12deg); } }
@media (prefers-reduced-motion: reduce) {
  ha-icon { animation: none; }
}

{% set state = states('sensor.siemens_016050395510002818_bsh_common_status_operationstate').split('.')[-1] %}
{% set value = states('sensor.siemens_016050395510002818_bsh_common_option_programprogress') %}
{% set valid = is_number(value) and 0 <= value | float(0) <= 100 %}
{% set progress = value | float(0) if valid else 0 %}
{% set color = '#FFC107' if state == 'Pause' else '#FF9800' if state in ['ActionRequired', 'Error'] else '#64b5c6' %}
ha-card { position: relative; overflow: hidden; }
ha-card::before, ha-card::after {
 content: '';
 position: absolute;
 bottom: 0;
 left: 0;
 height: 4px;
 pointer-events: none;
 opacity: {{ 1 if valid else 0 }};
}
ha-card::before { width: 100%; background: rgba(100,181,198,.15); }
ha-card::after {
 width: {{ progress }}%;
 background-color: {{ color }};
 background-image: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.35) 50%, transparent 70%);
 background-size: 90px 100%;
 transition: width 1s ease, background-color .5s ease;
 animation: {{ 'appliance-progress-flow 3s linear infinite' if state == 'Run' and valid and progress < 100 else 'none' }};
}
@keyframes appliance-progress-flow { from { background-position: 0 0; } to { background-position: 90px 0; } }
@media(prefers-reduced-motion:reduce) { ha-card::after { animation:none; transition:none; } }

